'use client'

import { useStrings, type StringsOverrides } from './strings'

import * as React from 'react'

import { Button } from './button'

// The shared rule sets, so the theme's action face and press gesture reach the
// controls this surface renders. GSUI-118: the file shipped and nothing
// imported it, so the classes matched nothing in a real install.
import './gamestage-primitives.css'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Discovery, and `tsc --noEmit` passes on it,
// so the gate cannot catch it.
import './discovery.css'

/**
 * Discovery: what there is to play, and the way into it.
 *
 * One tile per game, each saying which of three things is true of it: it is
 * live, it starts later, or it has ended. That is `data-gs-availability`, and
 * it is host-declared. The library holds no clock, so an upcoming game whose
 * countdown reaches zero stays upcoming until the host says otherwise, and a
 * tile never decides for itself that it is over.
 *
 * A tile is not a choice. Picking one is not answering a question, so it
 * carries `data-gs-item` and never `data-gs-choice`, `data-gs-selected` or
 * `data-gs-committed`. What it has instead is one control, whose label is the
 * verb of its outcome: join a live game, get a reminder about an upcoming
 * one, see the results of an ended one.
 *
 * Specimen 4f draws the arrangement and design/twins/4f.json measures ours
 * against it: the first game as a hero over its art, with the live pill, the
 * playing count and the words and the control laid over the picture; the rest
 * as a grid of cards with a compact control each; and under them the drawing's
 * third way in, a code. "entry: join, code, deep link" is the drawing's own
 * note, and the deep link is the host's URL, not a component.
 *
 * It performs nothing. It fetches no list, opens nothing, remembers no
 * reminder and redeems no code. `games` comes from the host and every press,
 * and every submitted code, is reported back.
 *
 * The art is the host's too, passed as a node. The library never owns a video
 * or an image source, and a tile without art is a token-filled placeholder
 * rather than a blank rectangle, for the same reason a media frame is.
 */

export type DiscoveryAvailability = 'live' | 'upcoming' | 'ended'

export interface DiscoveryGame {
  /** The game's id. Reaches `data-gs-item`, so a host can find its own tile. */
  id: string
  /** The game's name: "Monaco GP". */
  label: string
  /** Now, later, or over. Host-declared; the library has no clock. */
  availability: DiscoveryAvailability
  /** The line above the name: "Predictor, round 3 of 5". */
  kicker?: string
  /** How many are in it: "1,204 playing". Drawn as a pill with the room's symbols. */
  detail?: string
  /** What the status is: "Starts in", "You finished". */
  statusLabel?: string
  /** The status itself: "14:20", "#7". */
  statusValue?: string
  /** The picture, supplied by the host. Absent renders the placeholder. */
  art?: React.ReactNode
  /** The control's label, as the verb of its outcome: "Join", "Remind me". */
  actionLabel: string
  /** Called on that control. Everything behind it is the host's. */
  onAction: () => void
}

/** The drawing's third way in: "Have a code?", a field and GO. */
export interface DiscoveryCodeEntry {
  /** The question beside the field: "Have a code?". */
  label: string
  /** What an empty field shows: "ABC-123". */
  placeholder?: string
  /** The control's word: "GO". */
  actionLabel: string
  /** Called with whatever was typed, trimmed. Redeeming it is the host's. */
  onSubmit: (code: string) => void
}

export interface DiscoveryProps extends React.HTMLAttributes<HTMLElement> {
  /** Per-instance vocabulary, merged over the provider. */
  strings?: StringsOverrides

  /** The games to show, in the order the host wants them shown. */
  games: DiscoveryGame[]
  /** The list's accessible name: "Games", "Tonight's races". */
  label: string
  /** Render the first game as a full-width hero tile, as specimen 4f draws it. */
  featured?: boolean
  /** The code row under the tiles. Omit it and no row renders. */
  code?: DiscoveryCodeEntry
  /** The words the accessible name carries for each availability. */
  availabilityWords?: Record<DiscoveryAvailability, string>
}

/**
 * The contract fixes the English. A host may translate it; what may not change
 * is that the tile's name says which of the three is true.
 */

/**
 * The three symbols in front of the playing count. Symbols, not avatars, as
 * the drawing has them: the room's colours, standing for nobody in particular.
 */
const SYMBOLS = ['player', 'opponent', 'warning'] as const

export function Discovery(props: DiscoveryProps) {
  const { strings, ...componentProps } = props
  const copy = useStrings(strings)
  const AVAILABILITY_WORDS: Record<DiscoveryAvailability, string> = {
    live: copy['discovery.live'],
    upcoming: copy['discovery.upcoming'],
    ended: copy['discovery.ended'],
  }
  const {
    games,
    label,
    featured = false,
    code,
    availabilityWords = AVAILABILITY_WORDS,
    className,
    ...rest
  } = componentProps

  return (
    <section
      {...rest}
      className={['gs-discovery', className].filter(Boolean).join(' ')}
      data-gs-component="discovery"
      aria-label={label}
    >
      <ul
        className={['gs-discovery__list', featured ? 'gs-discovery__list--featured' : null]
          .filter(Boolean)
          .join(' ')}
        data-gs-scope="discovery"
        data-gs-part="list"
      >
        {games.map((game) => (
          <li
            key={game.id}
            className="gs-discovery__row"
            data-gs-scope="discovery"
            data-gs-part="row"
            data-gs-item={game.id}
            data-gs-availability={game.availability}
          >
            <div className="gs-discovery__media" data-gs-scope="discovery" data-gs-part="media">
              {game.art}
            </div>

            {/* Live and ended are pills a player sees, laid over the art. Upcoming
                is the one the drawing states with its countdown instead, so its
                word is in the name and not on screen: two ways of saying "later"
                on one tile is one too many. The live pill carries the pulse, which
                is motion and stops dead under reduced motion. */}
            <span
              className="gs-discovery__availability"
              data-gs-scope="discovery"
              data-gs-part="availability"
            >
              {game.availability === 'live' ? (
                <span
                  className="gs-discovery__pulse"
                  data-gs-scope="discovery"
                  data-gs-part="pulse"
                  data-gs-animates="motion"
                  aria-hidden="true"
                />
              ) : null}
              {availabilityWords[game.availability]}
            </span>

            {game.detail ? (
              <span className="gs-discovery__summary" data-gs-scope="discovery" data-gs-part="summary">
                <span className="gs-discovery__symbols" aria-hidden="true">
                  {SYMBOLS.map((symbol) => (
                    <span key={symbol} className={`gs-discovery__symbol gs-discovery__symbol--${symbol}`} />
                  ))}
                </span>
                {game.detail}
              </span>
            ) : null}

            {/* The words and the control together: a column on a card, a row
                laid along the bottom of the hero. */}
            <div className="gs-discovery__band">
              <div className="gs-discovery__words">
                {game.kicker ? (
                  <span className="gs-discovery__kicker" data-gs-scope="discovery" data-gs-part="detail">
                    {game.kicker}
                  </span>
                ) : null}

                <span className="gs-discovery__label" data-gs-scope="discovery" data-gs-part="label">
                  {game.label}
                </span>

                {game.statusLabel || game.statusValue ? (
                  <span className="gs-discovery__status">
                    {game.statusLabel ? (
                      <span className="gs-discovery__status-label">{game.statusLabel}</span>
                    ) : null}
                    {game.statusValue ? (
                      <span
                        className="gs-discovery__value"
                        data-gs-scope="discovery"
                        data-gs-part="value"
                      >
                        {game.statusValue}
                      </span>
                    ) : null}
                  </span>
                ) : null}
              </div>

              <div className="gs-discovery__actions" data-gs-scope="discovery" data-gs-part="actions">
                <Button
                  strings={copy}
                  variant={game.availability === 'live' ? 'primary' : 'secondary'}
                  onClick={game.onAction}
                >
                  {/* The label alone reads "Join" on four tiles in a list, so the
                      game's name goes in the accessible name too. */}
                  {game.actionLabel}
                  <span className="gs-discovery__announcement">{`, ${game.label}`}</span>
                </Button>
              </div>
            </div>
          </li>
        ))}
      </ul>

      {code ? (
        <form
          className="gs-discovery__code"
          data-gs-scope="discovery"
          data-gs-part="actions"
          onSubmit={(event) => {
            // Reported, never redeemed. The field is uncontrolled so the row
            // holds no state of its own; the host gets the text and owns what
            // happens next.
            event.preventDefault()
            const value = new FormData(event.currentTarget).get('code')
            code.onSubmit(typeof value === 'string' ? value.trim() : '')
          }}
        >
          <span className="gs-discovery__code-label">{code.label}</span>
          <input
            className="gs-discovery__field"
            data-gs-scope="discovery"
            data-gs-part="control"
            name="code"
            type="text"
            autoComplete="off"
            autoCapitalize="characters"
            placeholder={code.placeholder}
            aria-label={code.label}
          />
          <Button strings={copy} type="submit" variant="primary" data-gs-scope="discovery" data-gs-part="commit">
            {code.actionLabel}
          </Button>
        </form>
      ) : null}
    </section>
  )
}

/* Discovery. Every value comes from a token; nothing here is a literal colour.

   Specimen 4f draws the surface and design/twins/4f.json measures ours against
   it, tile by tile. Two shelves recur in the drawing and have no depth token:
   the 4px shelf under a card (drawn 27 times) and the 3px shelf under a 40px
   control (21 times). Both are composed here from a space or stroke token and
   the edge, and both are on the token request list. */

.gs-discovery {
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-inset);
  color: var(--gs-color-ink);
}

.gs-discovery__list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(9rem, 1fr));
  gap: var(--gs-space-gap);

  margin: 0;
  padding: 0;
  list-style: none;
}

/* ------------------------------------------------------------- a card -- */

.gs-discovery__row {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-2);
  box-sizing: border-box;
  padding: var(--gs-space-3);

  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-lg);
  box-shadow: 0 var(--gs-space-1) 0 var(--gs-color-edge);
}

/* A game that is over keeps its shape and steps back, so the list still reads
   as one list. It is never greyed out to the point of unreadable: the word
   "ended" is what says it, and the fade only agrees with the word. */
.gs-discovery__row[data-gs-availability='ended'] {
  opacity: 0.8;
  box-shadow: var(--gs-depth-flat);
}

/* Never a blank rectangle. Without art from the host this is still a surface a
   player can see, for the same reason a media frame keeps its poster. The
   height is the drawing's 70px card art at the nearest token. */
.gs-discovery__media {
  position: relative;
  block-size: var(--gs-size-action-large);
  overflow: hidden;

  background: repeating-linear-gradient(
    135deg,
    var(--gs-color-surface-raised-solid) 0 6px,
    var(--gs-color-surface-solid) 6px 12px
  );
  border-radius: var(--gs-radius-sm);
}

.gs-discovery__media > * {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* -- the state pills ------------------------------------------------------ */
/* Live and ended are pills over the art. The figure face, small; the drawing
   sets them at 9 and 10px, and 12 is the floor. */
.gs-discovery__availability {
  position: absolute;
  display: flex;
  align-items: center;
  gap: var(--gs-space-1);
  box-sizing: border-box;
  padding: 0 var(--gs-space-2);

  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  text-transform: uppercase;

  border-radius: var(--gs-radius-full);
}

/* Live: negative, ringed in the edge, top left, with the pulse in front. */
.gs-discovery__row[data-gs-availability='live'] .gs-discovery__availability {
  top: var(--gs-space-3);
  left: var(--gs-space-3);
  min-height: var(--gs-space-8);
  color: var(--gs-color-ink);
  background: var(--gs-color-negative);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
}

/* The pulse is motion: reduced motion takes `--gs-motion-pulse` to 0ms and it
   stops dead, and the word beside it still says live. */
.gs-discovery__pulse {
  flex: none;
  inline-size: var(--gs-space-2);
  block-size: var(--gs-space-2);
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-ink);
  animation: gs-discovery-pulse var(--gs-motion-pulse) var(--gs-motion-ease-pulse) infinite;
}

@keyframes gs-discovery-pulse {
  50% { opacity: 0.35; }
}

/* Ended: the edge, quiet ink, centred on the art. */
.gs-discovery__row[data-gs-availability='ended'] .gs-discovery__availability {
  top: calc(var(--gs-space-3) + var(--gs-size-action-large) / 2);
  left: 50%;
  transform: translate(-50%, -50%);
  min-height: var(--gs-size-icon-control);
  color: var(--gs-color-ink-secondary);
  background: var(--gs-color-edge);
}

/* Upcoming says the same thing with its countdown, so it is in the accessible
   name and not on screen. */
.gs-discovery__row[data-gs-availability='upcoming'] .gs-discovery__availability {
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  white-space: nowrap;
  clip-path: inset(50%);
  border: 0;
}

/* -- who is in it --------------------------------------------------------- */
/* The playing count: a hole punched in the surface, the room's symbols in
   front, the same idea as presence's count. */
.gs-discovery__summary {
  display: flex;
  align-items: center;
  align-self: flex-start;
  gap: var(--gs-space-1);
  box-sizing: border-box;
  min-height: var(--gs-space-8);
  padding: 0 var(--gs-space-2);

  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);

  background: var(--gs-color-edge);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge-high);
  border-radius: var(--gs-radius-full);
}

.gs-discovery__symbols { display: flex; }

.gs-discovery__symbol {
  box-sizing: border-box;
  inline-size: var(--gs-size-icon-utility);
  block-size: var(--gs-size-icon-utility);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
}

.gs-discovery__symbol + .gs-discovery__symbol { margin-inline-start: calc(-1 * var(--gs-space-1)); }

.gs-discovery__symbol--player { background: var(--gs-color-player-solid); }
.gs-discovery__symbol--opponent { background: var(--gs-color-opponent-solid); }
.gs-discovery__symbol--warning { background: var(--gs-color-warning-solid); }

/* -- the words and the control -------------------------------------------- */

.gs-discovery__band {
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-2);
}

.gs-discovery__words {
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-1);
  min-width: 0;
}

.gs-discovery__kicker {
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  color: var(--gs-color-warning-solid);
}

/* The name, in the figure face on a card and the title face on the hero. Tight
   leading, as the drawing sets every Unbounded title; one property borrowed
   from the action axis for the case, so the name shouts where the theme's
   primary action shouts. */
.gs-discovery__label {
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  line-height: 1.1;
  text-transform: var(--gs-type-action-text-transform-primary, var(--gs-type-action-text-transform, none));
}

.gs-discovery__status {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--gs-space-2);
}

.gs-discovery__status-label {
  font-family: var(--gs-type-eyebrow-font-family);
  font-size: var(--gs-type-eyebrow-font-size);
  font-weight: var(--gs-type-eyebrow-font-weight);
  color: var(--gs-color-ink-secondary);
}

.gs-discovery__value {
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
  color: var(--gs-color-warning-solid);
}

.gs-discovery__row[data-gs-availability='ended'] .gs-discovery__value {
  color: var(--gs-color-reward-solid);
}

.gs-discovery__actions {
  display: flex;
  gap: var(--gs-space-2);
}

.gs-discovery__actions > * { flex: 1 1 auto; }

/* The control on a card is compact: the small control height, the small
   radius, the label face, a 3px shelf. The button brings the raised face and
   the press gesture; this scopes its size to the card it sits on. */
.gs-discovery__actions .gs-button {
  min-height: var(--gs-size-control-small);
  /* The drawing gives the card's control no padding of its own and lets it
     fill the card; space.3 keeps "Remind me" on one line at a 136px card. */
  padding: 0 var(--gs-space-3);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-sm);
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: normal;
  box-shadow: 0 var(--gs-stroke-ui) 0 var(--gs-color-edge);
}

/* Results, on a game that is over: hollow and quiet, with no shelf. */
.gs-discovery__row[data-gs-availability='ended'] .gs-discovery__actions .gs-button {
  color: var(--gs-color-ink-secondary);
  background: transparent;
  box-shadow: var(--gs-depth-flat);
}

/* Join, on a live game: the interactive face at the touch height, the figure
   face in capitals. Its depth is the button's own. */
.gs-discovery__row[data-gs-availability='live'] .gs-discovery__actions .gs-button {
  min-height: var(--gs-size-touch-min);
  padding: 0 var(--gs-space-4);
  border-radius: var(--gs-radius-md);
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  box-shadow: var(--gs-depth-pressable);
}

/* --------------------------------------------------------------- the hero -- */
/* The first game across the full width, over its art: the pills at the top
   corners, the words and the control along the bottom, a scrim between. */
.gs-discovery__list--featured > .gs-discovery__row:first-child {
  grid-column: 1 / -1;
  display: grid;
  padding: 0;
  overflow: hidden;
  border-radius: var(--gs-radius-xl);
  box-shadow: 0 var(--gs-press-travel) 0 var(--gs-color-edge);
}

.gs-discovery__list--featured > .gs-discovery__row:first-child > * {
  grid-area: 1 / 1;
}

.gs-discovery__list--featured > .gs-discovery__row:first-child .gs-discovery__media {
  block-size: auto;
  aspect-ratio: 2 / 1;
  border-radius: 0;
}

/* The scrim over the art, so the words at the bottom read over any picture.
   Mixed from the edge rather than written as a colour. */
.gs-discovery__list--featured > .gs-discovery__row:first-child .gs-discovery__media::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 30%, color-mix(in oklch, var(--gs-color-edge) 85%, transparent));
}

.gs-discovery__list--featured > .gs-discovery__row:first-child .gs-discovery__summary {
  position: absolute;
  top: var(--gs-space-3);
  right: var(--gs-space-3);
  z-index: 1;
}

.gs-discovery__list--featured > .gs-discovery__row:first-child .gs-discovery__availability {
  z-index: 1;
}

.gs-discovery__list--featured > .gs-discovery__row:first-child .gs-discovery__band {
  position: relative;
  z-index: 1;
  flex-direction: row;
  align-items: flex-end;
  justify-content: space-between;
  align-self: end;
  gap: var(--gs-space-gap);
  margin: var(--gs-space-inset);
}

.gs-discovery__list--featured > .gs-discovery__row:first-child .gs-discovery__actions > * {
  flex: none;
}

.gs-discovery__list--featured > .gs-discovery__row:first-child .gs-discovery__label {
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
  line-height: var(--gs-type-title-line-height);
  /* One property borrowed from the display axis: the hero's name stands on the
     theme's display shadow. */
  text-shadow: var(--gs-type-display-shadow, none);
}

/* --------------------------------------------------------------- a code -- */
/* The drawing's third way in: a question, a field and GO, in one surface row. */
.gs-discovery__code {
  display: flex;
  align-items: center;
  gap: var(--gs-space-gap);
  box-sizing: border-box;
  /* The drawing's 56px row: the field's height with space.2 above and below.
     No size token is within 2px of it (chip is 52, action is 60), so it is
     composed rather than written, and it is on the token request list. */
  min-height: calc(var(--gs-size-control-small) + var(--gs-space-4));
  margin: 0;
  padding: 0 var(--gs-space-2) 0 var(--gs-space-inset);

  background: var(--gs-color-surface);
  border: var(--gs-stroke-ui) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-control);
}

.gs-discovery__code-label {
  flex: 1 1 auto;
  font-family: var(--gs-type-eyebrow-font-family);
  font-size: var(--gs-type-eyebrow-font-size);
  font-weight: var(--gs-type-eyebrow-font-weight);
}

/* The field is a hole in the surface, tracked capitals in the figure face. */
.gs-discovery__field {
  box-sizing: border-box;
  inline-size: 8rem;
  block-size: var(--gs-size-control-small);
  padding: 0 var(--gs-space-2);
  margin: 0;

  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  color: var(--gs-color-ink);

  background: var(--gs-color-edge);
  border: 0;
  border-radius: var(--gs-radius-sm);
}

.gs-discovery__field::placeholder { color: var(--gs-color-muted); }

.gs-discovery__field:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: 3px;
}

/* GO: the interactive face, compact and flat, as the drawing has it. */
.gs-discovery__code .gs-button {
  min-height: var(--gs-size-control-small);
  min-width: 0;
  padding: 0 var(--gs-space-3);
  border: 0;
  border-radius: var(--gs-radius-sm);
  font-family: var(--gs-type-figure-font-family);
  font-size: var(--gs-type-figure-font-size);
  font-weight: var(--gs-type-figure-font-weight);
  box-shadow: var(--gs-depth-flat);
}

/* In the accessible name, not on screen. Four tiles each offering "Join" are
   four identical controls to anyone reading them out. */
.gs-discovery__announcement {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  white-space: nowrap;
  clip-path: inset(50%);
  border: 0;
